const escapeHtml = value => String(value ?? "").replace(/[&<>'"]/g, character => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", "'": "&#39;", "\"": "&quot;" }[character]));
function path(file) { return `../${file}`; }
function imagePlaceholder(label, extra = "", image = "") { const source = image ? path(image) : ""; return `<div class="image-placeholder ${extra}">${source ? `<img src="${escapeHtml(source)}" alt="${escapeHtml(label)}" loading="lazy">` : `<span>${escapeHtml(label)}</span>`}</div>`; }
function button(label, href = "contact.html", primary = false) { return `<a class="button ${primary ? "button-primary" : "button-outline"}" href="${href}">${escapeHtml(label)} <span aria-hidden="true">→</span></a>`; }
function submitButton(label, primary = false) { return `<button class="button ${primary ? "button-primary" : "button-outline"}" type="submit">${escapeHtml(label)} <span aria-hidden="true">→</span></button>`; }
function sectionHeading(eyebrow, title, copy = "") { return `<div class="section-heading"><p class="eyebrow">${escapeHtml(eyebrow)}</p><h2>${escapeHtml(title)}</h2>${copy ? `<p>${escapeHtml(copy)}</p>` : ""}</div>`; }
function toArray(value) { return Array.isArray(value) ? value : []; }
function queryId() { return new URLSearchParams(window.location.search).get("id"); }
function selectedById(list, fallbackId) { return list.find(item => item.id === queryId()) || list.find(item => item.id === fallbackId) || list[0]; }
function safeUrl(file, id) { return `${file}?id=${encodeURIComponent(id || "")}`; }

function businessCards() { return `<div class="business-grid">${businesses.map(item => `<a class="business-card ${escapeHtml(item.tone)}" href="${escapeHtml(item.link)}"${item.image ? ` style="background-image:linear-gradient(180deg,rgba(3,21,45,.12),rgba(3,21,45,.9)),url('${escapeHtml(path(item.image))}')"` : ""}><span class="card-icon" aria-hidden="true">${escapeHtml(item.icon)}</span><h3>${escapeHtml(item.title)}</h3><p>${escapeHtml(item.text)}</p><span class="card-link">Explore ${escapeHtml(item.title)} <b aria-hidden="true">→</b></span></a>`).join("")}</div>`; }
function propertyCards(items = properties) { return `<div class="catalog-grid">${toArray(items).map(item => `<article class="catalog-card" id="${escapeHtml(item.id)}"><a href="${safeUrl("property-details.html", item.id)}">${imagePlaceholder(item.imageLabel || "Property View", "", item.image)}</a><div class="card-body"><span class="tag">${escapeHtml(item.type)}</span><h3>${escapeHtml(item.name)}</h3><div class="card-meta"><span>⌖ ${escapeHtml(item.location)}</span><span>${escapeHtml(item.bedrooms || "Property")}</span><span>${escapeHtml(item.size || "Details available")}</span></div><strong class="price">${escapeHtml(item.price)}</strong>${button("View Details", safeUrl("property-details.html", item.id))}</div></article>`).join("")}</div>`; }
function projectCards(items = projects) { return `<div class="catalog-grid">${toArray(items).map(item => `<article class="catalog-card" id="${escapeHtml(item.id)}"><a href="projects.html#${encodeURIComponent(item.id)}">${imagePlaceholder(item.imageLabel || item.status, "", item.image)}</a><div class="card-body"><span class="tag">${escapeHtml(item.status)}</span><h3>${escapeHtml(item.name)}</h3><p>⌖ ${escapeHtml(item.location)}</p><div class="card-meta"><span>${escapeHtml(item.detail)}</span><span>RIVROSS Developments</span></div>${item.progress ? `<div class="progress-track" aria-label="${escapeHtml(item.progress)} percent complete"><span style="width:${Math.min(100, Number(item.progress))}%"></span></div>` : ""}</div></article>`).join("")}</div>`; }
function teamCards(items = team) { return `<div class="team-grid">${toArray(items).map(person => `<article class="team-card" id="${escapeHtml(person.id)}">${imagePlaceholder(person.name || "Portrait", "", person.image)}<div class="card-body"><h3>${escapeHtml(person.name)}</h3><span class="role">${escapeHtml(person.role)}</span><p>${escapeHtml(person.bio || "Experienced professional focused on quality, integrity and long-term growth.")}</p><a class="text-link" href="leadership.html#${encodeURIComponent(person.id)}">View Profile <span aria-hidden="true">→</span></a></div></article>`).join("")}</div>`; }
function articleCards(items = articles) { return `<div class="article-grid">${toArray(items).map(item => `<article class="article-card" id="${escapeHtml(item.id)}">${imagePlaceholder(item.imageLabel || item.category, "", item.image)}<div class="card-body"><span class="tag">${escapeHtml(item.category)}</span><span class="date">${escapeHtml(item.date)} · ${escapeHtml(item.readTime || "5 min read")}</span><h3>${escapeHtml(item.title)}</h3><p>${escapeHtml(item.excerpt)}</p><a class="text-link" href="${safeUrl("news-details.html", item.id)}">Read More <span aria-hidden="true">→</span></a></div></article>`).join("")}</div>`; }
function serviceCards(items = services) { return `<div class="directory-grid service-directory">${toArray(items).map(item => `<article class="directory-card">${item.image ? imagePlaceholder(item.title, "service-image", item.image) : `<span aria-hidden="true">${escapeHtml(item.icon)}</span>`}<h3>${escapeHtml(item.title)}</h3><p>${escapeHtml(item.text)}</p>${button("Learn More", "contact.html")}</article>`).join("")}</div>`; }
function eventCards(items = events) { return `<div class="event-grid">${toArray(items).map(item => `<article class="event-card" id="${escapeHtml(item.id)}"><div class="event-top"><span class="tag">${escapeHtml(item.category)}</span><span class="meta">${escapeHtml(item.date)}</span></div>${imagePlaceholder(item.imageLabel || "Event", "event-image", item.image)}<h3>${escapeHtml(item.title)}</h3><p class="meta">⌖ ${escapeHtml(item.location)}</p><p>${escapeHtml(item.excerpt)}</p><div>${button("View Details", safeUrl("event-details.html", item.id))} ${button("Register Now", "business-inquiry.html", true)}</div></article>`).join("")}</div>`; }
function jobCards(items = jobs) { return `<div class="job-grid">${toArray(items).map(job => `<article class="job-card" id="${escapeHtml(job.id)}"><div class="job-top"><h3>${escapeHtml(job.title)}</h3><span class="tag">${escapeHtml(job.type)}</span></div><span class="meta">⌖ ${escapeHtml(job.location)} · ${escapeHtml(job.experience)}</span><p>${escapeHtml(job.description)}</p>${button("View Details", safeUrl("job-details.html", job.id))}</article>`).join("")}</div>`; }

function renderAbout() { return `<section class="page-section"><div class="site-container page-two-col"><div>${sectionHeading("Our Story", "Building Businesses. Creating Opportunities.", "RIVROSS was founded with a simple but powerful vision: to redefine real estate through integrity, innovation and quality. What started as a small team with big dreams has grown into a diversified organization with a strong presence in multiple sectors.")}${button("Download Corporate Profile", "business-inquiry.html", true)}</div>${imagePlaceholder("Our Story Visual", "visual-panel", "assets/images/site/about-cityline.png")}</div></section><section class="page-section soft"><div class="site-container">${sectionHeading("Our Core Values", "The Values That Define Us", "The principles that guide our decisions and relationships.")}<div class="value-grid">${["Integrity", "Excellence", "Innovation", "Teamwork", "Responsibility", "Respect"].map((x, i) => `<article class="value-card"><span aria-hidden="true">${["⬡", "✦", "⌁", "♧", "◉", "♢"][i]}</span><h3>${x}</h3><p>We uphold the highest standards and turn our values into meaningful action.</p></article>`).join("")}</div></div></section><section class="page-section dark"><div class="site-container">${sectionHeading("Leadership That Inspires", "Guided by Experience. Driven by Purpose.")} ${teamCards(team.slice(0, 4))}</div></section>`; }
function renderCompanies() { return `<section class="page-section"><div class="site-container">${sectionHeading("Diversified Businesses", "One Vision. Multiple Businesses.", "Our diverse business portfolio allows us to create value across industries and deliver sustainable growth for our clients, partners and communities.")}${businessCards()}</div></section><section class="page-section dark"><div class="site-container"><div class="stat-grid">${[["3+", "Business Verticals"], ["100+", "Projects Completed"], ["50+", "Expert Professionals"], ["500+", "Happy Clients"]].map(x => `<div class="stat-card"><strong>${x[0]}</strong><span>${x[1]}</span></div>`).join("")}</div></div></section><section class="page-section"><div class="site-container page-two-col"><div>${sectionHeading("Our Commitment", "Looking for Business Opportunities?", "Partner with us and be a part of our growth journey.")}${button("Send an Inquiry", "business-inquiry.html", true)}</div>${imagePlaceholder("Partnership Visual", "visual-panel", "assets/images/site/business-partnership.png")}</div></section>`; }

function propertySearchForm(mode = "all") { const list = properties; const locations = [...new Set(list.map(item => item.location.split(",")[0]))].sort(); const types = [...new Set(list.map(item => item.type))].sort(); const statuses = [...new Set(list.map(item => item.status))].sort(); return `<form class="catalog-toolbar" data-property-search data-property-mode="${mode}"><label>Keyword<input name="q" type="search" placeholder="Search properties..."></label><label>Location<select name="location"><option value="">All Locations</option>${locations.map(value => `<option value="${escapeHtml(value)}">${escapeHtml(value)}</option>`).join("")}</select></label><label>Property Type<select name="type"><option value="">All Types</option>${types.map(value => `<option value="${escapeHtml(value)}">${escapeHtml(value)}</option>`).join("")}</select></label><label>Status<select name="status"><option value="">All Status</option>${statuses.map(value => `<option value="${escapeHtml(value)}">${escapeHtml(value)}</option>`).join("")}</select></label><label>Price Range<select name="price"><option value="">All Price Ranges</option><option value="under-10000">Under BDT 10,000</option><option value="10000-plus">BDT 10,000+</option></select></label>${submitButton("Search Properties", true)}</form>`; }
function renderRealEstate() { return `<section class="page-section"><div class="site-container page-two-col"><div>${sectionHeading("Overview", "Creating Value. Building Trust.", "We develop residential, commercial and mixed-use properties that enhance communities and create sustainable value for our customers and investors.")}${button("Download Brochure", "business-inquiry.html", true)}</div>${imagePlaceholder("Premium Development", "visual-panel", "assets/images/site/project-city-center.png")}</div></section><section class="page-section soft"><div class="site-container">${propertySearchForm("featured")}${sectionHeading("Featured Properties", "Find Your Perfect Property") }<div data-property-summary class="search-summary"></div><div data-property-results>${propertyCards(properties.filter(item => item.featured).slice(0, 4))}</div></div></section><section class="page-section dark"><div class="site-container">${sectionHeading("Why Choose RIVROSS Real Estate?", "Built for Confidence")}<div class="value-grid">${["Quality Construction", "Prime Locations", "Modern Design", "End-to-End Service", "After Sales Support"].map(x => `<article class="value-card stat-card"><span>✦</span><h3>${x}</h3><p>Built around trust, clarity and long-term value.</p></article>`).join("")}</div></div></section>`; }
function renderProperties() { return `<section class="page-section"><div class="site-container">${sectionHeading("Property Listing", "A Place for Every Ambition", "Browse our curated residential, commercial and land opportunities.")}${propertySearchForm("all")}<div data-property-summary class="search-summary"></div><div data-property-results>${propertyCards()}</div></div></section><section class="page-section soft"><div class="site-container">${sectionHeading("Why Invest With RIVROSS?", "Confidence at Every Step")}${serviceCards(services.slice(5, 8))}</div></section>`; }
function projectSearchForm() { return `<form class="catalog-toolbar" data-project-search><label>Keyword<input name="q" type="search" placeholder="Search projects..."></label><label>Status<select name="status"><option value="">All Status</option><option>Ongoing</option><option>Upcoming</option><option>Completed</option></select></label><label>Location<input name="location" type="search" placeholder="All locations"></label>${submitButton("Filter Projects", true)}</form>`; }
function renderProjects() { return `<section class="page-section"><div class="site-container">${sectionHeading("Development Portfolio", "Creating Better Places to Live", "Explore ongoing, upcoming and completed RIVROSS developments.")}${projectSearchForm()}<div data-project-summary class="search-summary"></div><div data-project-results>${projectCards()}</div></div></section><section class="page-section dark"><div class="site-container">${sectionHeading("Build With RIVROSS", "A Track Record You Can Trust", "From planning to delivery, our teams stay focused on quality and long-term value.")}${button("Discuss Your Project", "business-inquiry.html", true)}</div></section>`; }
function renderTravel() { return `<section class="page-section dark"><div class="site-container">${sectionHeading("Why Choose RIVROSS?", "Your Journey, Our Commitment", "Transparent pricing, experienced support, reliable partners and safe, comfortable travel.")}${serviceCards(services.slice(0, 5))}</div></section><section class="page-section"><div class="site-container">${sectionHeading("Our Services", "Complete Travel Solutions")}${serviceCards(services.slice(0, 5))}</div></section><section class="page-section soft"><div class="site-container page-two-col"><div>${sectionHeading("Plan Your Journey", "Let's Make It Happen", "Share your travel plans and our team will get back to you with the best options.")}${button("Send an Inquiry", "business-inquiry.html", true)}</div>${imagePlaceholder("Travel Visual", "visual-panel", "assets/images/site/travel-tour.png")}</div></section>`; }
function renderTea() { return `<section class="page-section dark"><div class="site-container">${sectionHeading("Our Promise", "Quality Tea for Every Need", "Carefully sourced, responsibly handled and supplied with consistency.")}${serviceCards(services.slice(5, 8))}</div></section><section class="page-section"><div class="site-container page-two-col reverse">${imagePlaceholder("Tea Garden Visual", "visual-panel tall", "assets/images/site/tea-sourcing.png")}<div>${sectionHeading("Why Choose RIVROSS Tea?", "A Commitment to Excellence")}<ul class="check-list"><li>100% authentic Bangladeshi tea</li><li>Consistent quality, taste and aroma</li><li>Competitive wholesale prices</li><li>Flexible supply for all business sizes</li><li>Reliable long-term partnership</li></ul>${button("Business Inquiry", "business-inquiry.html", true)}</div></div></section>`; }
function renderServices() { return `<section class="page-section"><div class="site-container">${sectionHeading("Our Capabilities", "Professional Support Across Our Businesses", "From travel and property to business partnerships, our services are built around reliability and clear communication.")}${serviceCards()}</div></section><section class="page-section dark"><div class="site-container page-two-col"><div>${sectionHeading("Work With Us", "Built Around Your Goals", "Tell us what you need and we will connect you to the right RIVROSS team.")}${button("Start a Conversation", "business-inquiry.html", true)}</div>${imagePlaceholder("Service Visual", "visual-panel", "assets/images/site/business-partnership.png")}</div></section>`; }
function renderLeadership() { return `<section class="page-section"><div class="site-container">${sectionHeading("Our Management Team", "Experience. Vision. Leadership.", "Our management team brings together experience in real estate, development, finance and operations to drive sustainable growth.")}${teamCards()}</div></section><section class="page-section dark"><div class="site-container"><div class="stat-grid">${[["100+", "Team Members"], ["25+", "Years of Combined Experience"], ["50+", "Successful Projects"], ["20+", "Industry Awards"]].map(x => `<div class="stat-card"><strong>${x[0]}</strong><span>${x[1]}</span></div>`).join("")}</div></div></section>`; }

function renderNews() { const categories = [...new Set(articles.map(item => item.category))].sort(); return `<section class="page-section"><div class="site-container"><form class="catalog-toolbar" data-news-search><label>Category<select name="category"><option value="">All News</option>${categories.map(category => `<option value="${escapeHtml(category)}">${escapeHtml(category)}</option>`).join("")}</select></label><label>Search<input name="q" type="search" placeholder="Search articles..."></label>${submitButton("Search News", true)}</form><div data-news-summary class="search-summary"></div><div data-news-results>${sectionHeading("Latest Updates", "Stories From RIVROSS", "Stay informed on our work, our markets and the opportunities ahead.")}${articleCards()}</div></div></section><section class="page-section dark"><div class="site-container page-two-col"><div>${sectionHeading("Stay Updated", "Get the Latest From RIVROSS", "Subscribe for news, insights and announcements.")}</div><form class="form-panel" data-demo-form><div class="form-field"><label for="news-email">Email Address</label><input id="news-email" type="email" placeholder="Enter your email address" required></div>${submitButton("Subscribe", true)}</form></div></section>`; }
function renderEvents() { const categories = [...new Set(events.map(item => item.category))].sort(); return `<section class="page-section"><div class="site-container">${sectionHeading("Upcoming Events", "Connections That Last", "Meet industry leaders, exchange ideas and build partnerships through our events.")}<form class="catalog-toolbar" data-event-search><label>Search<input name="q" type="search" placeholder="Search events..."></label><label>Category<select name="category"><option value="">All Categories</option>${categories.map(category => `<option value="${escapeHtml(category)}">${escapeHtml(category)}</option>`).join("")}</select></label>${submitButton("Search Events", true)}</form><div data-event-summary class="search-summary"></div><div data-event-results>${eventCards()}</div></div></section><section class="page-section soft"><div class="site-container">${sectionHeading("Why Attend Our Events?", "Learn, Connect, Grow")}${serviceCards(services.slice(0, 5))}</div></section>`; }
function renderCareers() { return `<section class="page-section"><div class="site-container page-two-col">${imagePlaceholder("RIVROSS Team Visual", "visual-panel", "assets/images/site/careers-teamwork.png")}<div>${sectionHeading("About Careers at RIVROSS", "Where Ambition Meets Opportunity", "We are more than a real estate company; we are a team of visionaries, problem-solvers and change-makers.")}${button("Learn More About Us", "about.html")}</div></div></section><section class="page-section dark"><div class="site-container">${sectionHeading("Why Join RIVROSS?", "A Better Place to Grow")}${serviceCards(services.slice(0, 5))}</div></section><section class="page-section"><div class="site-container">${sectionHeading("Open Positions", "Find Your Next Opportunity")}${jobCards()}</div></section>`; }
