function itemSearchText(item) { return Object.values(item).filter(value => typeof value === "string").join(" ").toLowerCase(); }
function updateQuery(values) { const params = new URLSearchParams(window.location.search); Object.entries(values).forEach(([key, value]) => value ? params.set(key, value) : params.delete(key)); const query = params.toString(); window.history.replaceState({}, "", `${window.location.pathname}${query ? `?${query}` : ""}`); }
function filterProperties(form) { const formData = new FormData(form); const q = String(formData.get("q") || "").toLowerCase().trim(); const location = String(formData.get("location") || "").toLowerCase(); const type = String(formData.get("type") || "").toLowerCase(); const status = String(formData.get("status") || "").toLowerCase(); const price = String(formData.get("price") || ""); const filtered = properties.filter(item => (!q || itemSearchText(item).includes(q)) && (!location || item.location.toLowerCase().startsWith(location)) && (!type || item.type.toLowerCase() === type) && (!status || item.status.toLowerCase() === status) && (!price || price === "under-10000" && item.priceValue < 10000 || price === "10000-plus" && item.priceValue >= 10000)); const mode = form.dataset.propertyMode; const output = form.parentElement.querySelector("[data-property-results]"); const summary = form.parentElement.querySelector("[data-property-summary]"); const visible = mode === "featured" && !q && !location && !type && !status && !price ? filtered.filter(item => item.featured).slice(0, 4) : filtered; if (output) output.innerHTML = visible.length ? propertyCards(visible) : `<div class="notice no-results"><p>No properties matched these filters. Try another location, type or price range.</p></div>`; if (summary) summary.textContent = `Showing ${visible.length} of ${filtered.length} matching ${filtered.length === 1 ? "property" : "properties"}.`; updateQuery({ q, location, type, status, price }); }
function filterNews(form) { const formData = new FormData(form); const q = String(formData.get("q") || "").toLowerCase().trim(); const category = String(formData.get("category") || "").toLowerCase(); const filtered = articles.filter(item => (!q || itemSearchText(item).includes(q)) && (!category || item.category.toLowerCase() === category)); const output = form.parentElement.querySelector("[data-news-results]"); const summary = form.parentElement.querySelector("[data-news-summary]"); if (output) output.innerHTML = filtered.length ? `${sectionHeading("Latest Updates", "Stories From RIVROSS", "Stay informed on our work, our markets and the opportunities ahead.")}${articleCards(filtered)}` : `<div class="notice no-results"><p>No news articles matched your search.</p></div>`; if (summary) summary.textContent = `Showing ${filtered.length} of ${articles.length} articles.`; updateQuery({ q, category }); }
function filterProjects(form) { const formData = new FormData(form); const q = String(formData.get("q") || "").toLowerCase().trim(); const status = String(formData.get("status") || "").toLowerCase(); const location = String(formData.get("location") || "").toLowerCase().trim(); const filtered = projects.filter(item => (!q || itemSearchText(item).includes(q)) && (!status || item.status.toLowerCase() === status) && (!location || item.location.toLowerCase().includes(location))); const output = form.parentElement.querySelector("[data-project-results]"); const summary = form.parentElement.querySelector("[data-project-summary]"); if (output) output.innerHTML = filtered.length ? projectCards(filtered) : `<div class="notice no-results"><p>No projects matched your filters.</p></div>`; if (summary) summary.textContent = `Showing ${filtered.length} of ${projects.length} projects.`; updateQuery({ q, status, location }); }
function filterEvents(form) { const formData = new FormData(form); const q = String(formData.get("q") || "").toLowerCase().trim(); const category = String(formData.get("category") || "").toLowerCase(); const filtered = events.filter(item => (!q || itemSearchText(item).includes(q)) && (!category || item.category.toLowerCase() === category)); const output = form.parentElement.querySelector("[data-event-results]"); const summary = form.parentElement.querySelector("[data-event-summary]"); if (output) output.innerHTML = filtered.length ? eventCards(filtered) : `<div class="notice no-results"><p>No events matched your search.</p></div>`; if (summary) summary.textContent = `Showing ${filtered.length} of ${events.length} events.`; updateQuery({ q, category }); }
function searchEverything(form) { const q = String(new FormData(form).get("q") || "").toLowerCase().trim(); const result = document.querySelector("[data-site-results]"); const summary = document.querySelector("[data-site-summary]"); if (!q) return; const groups = [{ label: "Properties", items: properties.filter(item => itemSearchText(item).includes(q)), render: items => propertyCards(items) }, { label: "Projects", items: projects.filter(item => itemSearchText(item).includes(q)), render: items => projectCards(items) }, { label: "News & Insights", items: articles.filter(item => itemSearchText(item).includes(q)), render: items => articleCards(items) }, { label: "Events", items: events.filter(item => itemSearchText(item).includes(q)), render: items => eventCards(items) }, { label: "Services", items: services.filter(item => itemSearchText(item).includes(q)), render: items => serviceCards(items) }, { label: "Businesses", items: businesses.filter(item => itemSearchText(item).includes(q)), render: items => `<div class="business-grid">${items.map(item => `<a class="business-card ${escapeHtml(item.tone)}" href="${escapeHtml(item.link)}"><span class="card-icon">${escapeHtml(item.icon)}</span><h3>${escapeHtml(item.title)}</h3><p>${escapeHtml(item.text)}</p><span class="card-link">Explore ${escapeHtml(item.title)} <b aria-hidden="true">→</b></span></a>`).join("")}</div>` }].filter(group => group.items.length); const total = groups.reduce((sum, group) => sum + group.items.length, 0); if (summary) summary.textContent = `${total} result${total === 1 ? "" : "s"} found for “${q}”.`; if (result) result.innerHTML = groups.length ? groups.map(group => `<section class="search-group"><h2>${escapeHtml(group.label)}</h2>${group.render(group.items)}</section>`).join("") : `<div class="notice no-results"><p>No site results matched “${escapeHtml(q)}”. Try a property name, location, project, news topic or service.</p></div>`; updateQuery({ q }); }

function restoreSearchState() { const params = new URLSearchParams(window.location.search); document.querySelectorAll("[data-property-search], [data-news-search], [data-project-search], [data-event-search], [data-site-search]").forEach(form => { let restored = false; form.querySelectorAll("[name]").forEach(control => { const value = params.get(control.name); if (value !== null) { control.value = value; restored = true; } }); if (restored) { if (form.matches("[data-property-search]")) filterProperties(form); else if (form.matches("[data-news-search]")) filterNews(form); else if (form.matches("[data-project-search]")) filterProjects(form); else if (form.matches("[data-event-search]")) filterEvents(form); else if (form.matches("[data-site-search]")) searchEverything(form); } }); }
function bindDynamicSearch() { document.querySelectorAll("[data-property-search]").forEach(form => { const run = () => filterProperties(form); form.addEventListener("submit", event => { event.preventDefault(); run(); }); form.querySelectorAll("input, select").forEach(control => control.addEventListener("change", run)); }); document.querySelectorAll("[data-news-search]").forEach(form => form.addEventListener("submit", event => { event.preventDefault(); filterNews(form); })); document.querySelectorAll("[data-project-search]").forEach(form => form.addEventListener("submit", event => { event.preventDefault(); filterProjects(form); })); document.querySelectorAll("[data-event-search]").forEach(form => form.addEventListener("submit", event => { event.preventDefault(); filterEvents(form); })); document.querySelectorAll("[data-site-search]").forEach(form => form.addEventListener("submit", event => { event.preventDefault(); searchEverything(form); })); restoreSearchState(); }
function bindNavigation() { const toggle = document.querySelector("[data-menu-toggle]"); const menu = document.querySelector("[data-menu]"); toggle?.addEventListener("click", () => { const open = toggle.getAttribute("aria-expanded") === "true"; toggle.setAttribute("aria-expanded", String(!open)); menu.classList.toggle("is-open", !open); }); const dropdown = document.querySelector("[data-dropdown]"); const dropdownButton = dropdown?.querySelector("button"); dropdownButton?.addEventListener("click", () => { const open = dropdownButton.getAttribute("aria-expanded") === "true"; dropdownButton.setAttribute("aria-expanded", String(!open)); dropdown.classList.toggle("is-open", !open); }); }
function bindDemoForms() { document.querySelectorAll("[data-demo-form]").forEach(form => form.addEventListener("submit", event => { event.preventDefault(); form.querySelector(".notice")?.remove(); const note = document.createElement("p"); note.className = "notice"; note.innerHTML = "Thanks — your request is ready to connect to the preferred email or form backend."; form.append(note); })); }

async function setupPage() {
  const loaded = await (window.RIVROSS_DATA_PROMISE || Promise.resolve(FALLBACK_DATA));
  businesses = toArray(loaded.businesses || FALLBACK_DATA.businesses);
  properties = toArray(loaded.properties || FALLBACK_DATA.properties);
  projects = toArray(loaded.projects || FALLBACK_DATA.projects);
  team = toArray(loaded.team || FALLBACK_DATA.team);
  articles = toArray(loaded.news || FALLBACK_DATA.news);
  events = toArray(loaded.events || FALLBACK_DATA.events);
  jobs = toArray(loaded.jobs || FALLBACK_DATA.jobs);
  services = toArray(loaded.services || FALLBACK_DATA.services);
  const key = document.body.dataset.page || "404";
  const page = PAGE_DATA[key] || PAGE_DATA["404"];
  const activePage = key === "companies" ? "companies" : key;
  document.title = `RIVROSS | ${page.title.replace(/,$/, "")} ${page.highlight}`;
  document.querySelector("[data-shell-header]").innerHTML = renderHeader(activePage);
  document.querySelector("[data-shell-footer]").innerHTML = renderFooter();
  const innerHero = document.querySelector("[data-inner-hero]");
  innerHero.style.setProperty("--hero-image", page.heroImage ? `url('${escapeHtml(path(page.heroImage))}')` : "none");
  innerHero.innerHTML = `<div class="site-container inner-hero-copy"><div class="breadcrumbs"><a href="${path("index.html")}">Home</a><span>›</span><span>${escapeHtml(page.eyebrow)}</span></div><h1>${escapeHtml(page.title)}<span>${escapeHtml(page.highlight)}</span></h1><div class="gold-rule"></div><p>${escapeHtml(page.intro)}</p></div>`;
  document.querySelector("[data-page-content]").innerHTML = page.render();
  bindNavigation();
  bindDynamicSearch();
  bindDemoForms();
}

document.addEventListener("DOMContentLoaded", setupPage);
